// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testFuzz_property(address recipient, uint256 startingBalance) public {
        vm.assume(recipient != address(this) && recipient != address(c) && recipient.code.length == 0 && recipient != address(0));
        vm.deal(address(c), 1000 ether);
        uint256 contractBalanceBefore = address(c).balance;

        vm.deal(recipient, 0);
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this) && recipient.code.length == 0);
        vm.deal(address(c), 200 ether);
        c.getFirstWithdrawalBonus(recipient);
        uint256 balBefore = address(c).balance;
        c.withdrawReward(recipient);
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore, "contract balance should not change on second withdraw");
    }
}
